natv2SubscriberPortMapEntries = MibTableColumn((1, 3, 6, 1, 2, 1, 234, 1, 1, 1, 7), Unsigned32()).setMaxAccess("readonly")
if mibBuilder.loadTexts: natv2SubscriberPortMapEntries.setReference('RFC 7659, Section 3.3.9.')
if mibBuilder.loadTexts: natv2SubscriberPortMapEntries.setStatus('current')
if mibBuilder.loadTexts: natv2SubscriberPortMapEntries.setDescription("The current number of port map entries in the port map table\n         for the subscriber, including static mappings.  A port map\n         entry maps from a given external realm, address, and port\n         for a given protocol to an internal realm, address, and\n         port.  This definition includes 'hairpin' mappings, where the\n         external realm is the same as the internal one.  Port map\n         entries are also tracked per instance and per protocol and\n         address pool within the instance.")
natv2SubscriberTranslations = MibTableColumn((1, 3, 6, 1, 2, 1, 234, 1, 1, 1, 8), Counter64()).setMaxAccess("readonly")
if mibBuilder.loadTexts: natv2SubscriberTranslations.setStatus('current')
if mibBuilder.loadTexts: natv2SubscriberTranslations.setDescription("The cumulative number of translated packets received from or\n         sent to this subscriber.  This value MUST be monotone\n         increasing in the periods between updates of the entity's\n         natv2SubscriberDiscontinuityTime.  If a manager detects a\n         change in the latter since the last time it sampled this\n\n\n\n\n\n         counter, it SHOULD NOT make use of the difference between\n         the latest value of the counter and any value retrieved\n         before the new value of natv2SubscriberDiscontinuityTime.")
natv2SubscriberAddressMapCreations = MibTableColumn((1, 3, 6, 1, 2, 1, 234, 1, 1, 1, 9), Counter64()).setMaxAccess("readonly")
if mibBuilder.loadTexts: natv2SubscriberAddressMapCreations.setStatus('current')
if mibBuilder.loadTexts: natv2SubscriberAddressMapCreations.setDescription("The cumulative number of address map entries created for\n         this subscriber, including static mappings.  Address map\n         entries are also tracked per instance and per protocol and\n         address pool within the instance.\n\n         This value MUST be monotone increasing in\n         the periods between updates of the entity's\n         natv2SubscriberDiscontinuityTime.  If a manager detects a\n         change in the latter since the last time it sampled this\n         counter, it SHOULD NOT make use of the difference between\n         the latest value of the counter and any value retrieved\n         before the new value of natv2SubscriberDiscontinuityTime.")
